{
  "name": "西门子 S7 可编程逻辑控制器",
  "name_en": "Siemens S7 Programmable Logic Controller",
  "manufacturer": "Siemens",
  "description": "这是一类工业可编程逻辑控制器（PLC），常用于实验室自动化、测试台控制、设备联锁、数据采集与顺序控制。该设备通常通过以太网使用 ISO on TCP / S7 通信协议与上位机交换控制命令和过程数据。",
  "description_en": "This is an industrial programmable logic controller (PLC) commonly used for laboratory automation, test stand control, equipment interlocks, data acquisition, and sequence control. It typically communicates with host systems over Ethernet using the ISO on TCP / S7 protocol to exchange control commands and process data.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "建立与 S7 PLC 的 ISO on TCP 通信连接。",
      "description_en": "Establish an ISO on TCP communication connection to the S7 PLC."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与 S7 PLC 的 ISO on TCP 通信连接。",
      "description_en": "Disconnect the ISO on TCP communication connection from the S7 PLC."
    },
    {
      "action_name": "auto-send_data",
      "description": "向 S7 PLC 发送过程数据或控制报文。",
      "description_en": "Send process data or control telegrams to the S7 PLC."
    },
    {
      "action_name": "auto-receive_data",
      "description": "接收来自 S7 PLC 的过程数据或响应报文。",
      "description_en": "Receive process data or response telegrams from the S7 PLC."
    },
    {
      "action_name": "auto-check_connection",
      "description": "检查与 S7 PLC 的通信连接是否仍然有效。",
      "description_en": "Check whether the communication connection to the S7 PLC is still active."
    }
  ],
  "tag_hints": [
    "Siemens S7",
    "PLC automation",
    "industrial control",
    "ISO on TCP",
    "S7 communication",
    "Ethernet PLC",
    "test stand control"
  ]
}

